--Q1. What is the total revenue generated by male vs female customers?
select gender, 
SUM(purchase_amount) as revenue
from customer
group by gender;

--Q2. Which customers used a discount but still spend at least the averagae purchase amount?
select customer_id, purchase_amount
from customer
where discount_applied = 'Yes' and purchase_amount >= (select avg(purchase_amount) from customer);

--Q3. Which are the top 5 products with the highest review rating?
select item_purchased, ROUND(avg(review_rating::numeric),2) as "Average Product Rating"
from customer
group by item_purchased
order by avg(review_rating) desc
limit 5;

-- Q4. Compare average purchase amounts across shipping types
SELECT
    shipping_type,
    ROUND(AVG(purchase_amount), 2) AS avg_purchase_amount
FROM customer
GROUP BY shipping_type
ORDER BY avg_purchase_amount DESC;

--Q5. Do subscribed customers spend more? 
--Compare avg spend and total revenue between subscribers and non subscribers.
select subscription_status,
count(customer_id) as total_customers,
round(avg(purchase_amount),2) as avg_spend,
round(sum(purchase_amount),2) as total_revenue
from customer
group by subscription_status
order by total_revenue desc;

--Q6. Which 5 products have the highest percentage of purchases with discount applied?
select item_purchased,
round(100.0 * sum(case when discount_applied = 'Yes' then 1 else 0 end)/count(*), 2) as discount_rate
from customer
group by item_purchased
order by discount_rate desc
limit 5;

--Q7. Segment customers into New, Returning and loyal based on their total number of previous purchases 
--and show the count of each segment?
WITH customer_type AS (
    SELECT 
        customer_id,
        previous_purchases,
        CASE
            WHEN previous_purchases = 1 THEN 'New'
            WHEN previous_purchases BETWEEN 2 AND 10 THEN 'Returning'
            ELSE 'Loyal'
        END AS customer_segment
    FROM customer
)

SELECT 
    customer_segment,
    COUNT(*) AS "Number of Customers"
FROM customer_type
GROUP BY customer_segment;

--Q8. What are the top 3 most purchased products within each category?
with item_counts as (
	select
		category, 
		item_purchased,
		count(customer_id) as total_orders,
		dense_rank() over(
			partition by category 
			order by count(customer_id) desc
		) as item_rank
	from customer
	group by category, item_purchased
)

select item_rank, category, item_purchased, total_orders
from item_counts
where item_rank <= 3;


-- Q9. Are repeat buyers (>5 previous purchases) more likely to subscribe?
SELECT
    subscription_status,
    COUNT(customer_id) AS repeat_buyers,
    ROUND(
        COUNT(customer_id) * 100.0 /
        SUM(COUNT(customer_id)) OVER (),
        2
    ) AS percentage
FROM customer
WHERE previous_purchases > 5
GROUP BY subscription_status
ORDER BY percentage DESC;

--Q10. What is the revenue contribution of each age group?
select age_group, sum(purchase_amount) as total_revenue
from customer
group by age_group
order by total_revenue desc;